#!/usr/bin/env python3
"""Require explicit feature proofs from clean reports generated by the release commit."""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import re
import zipfile

from acceptance_evidence import source_identity
from global_feature_evidence import FEATURE_ID, PROOF_ID, verify_global_features

ROOT = Path(__file__).resolve().parents[1]


def scoped_removals(inventory: dict, baseline: dict, category: str, active_ids: list[str]) -> set[str]:
    reference = inventory.get("scopeRemovals")
    if not reference and not baseline.get("scopeRemovals"):
        return set()
    if reference != "eng/acceptance/scope-removals.json" or baseline.get("scopeRemovals") != reference:
        raise RuntimeError("Scoped baseline subtraction requires its exact reviewed removal audit.")
    path = (ROOT / reference).resolve()
    if not path.is_relative_to(ROOT.resolve()) or not path.is_file():
        raise RuntimeError("The reviewed scope-removal audit is missing or outside the repository.")
    audit = json.loads(path.read_text(encoding="utf-8"))
    revision = baseline.get("baselineRevision", baseline.get("baseline"))
    if (audit.get("schemaVersion") != 1 or audit.get("previousBaselineRevision") != revision
            or not audit.get("authorization") or audit.get("releaseReady") is True):
        raise RuntimeError("Scope removal is not release certification and needs its original reviewed baseline.")
    field = "featureId" if category == "removedFeatures" else "configurationId"
    rows = audit.get(category)
    if not isinstance(rows, list) or not rows:
        raise RuntimeError("The scope-removal audit has no explicit retired identities.")
    removed = set()
    for row in rows:
        identity = row.get(field)
        if (not isinstance(identity, str) or not identity or identity in removed or identity in active_ids
                or row.get("originalRequirement", {}).get(field) != identity or not row.get("reason")
                or row.get("status") in ("passed", "complete", "implementationReady") or row.get("receipt") is not None):
            raise RuntimeError("A scoped removal is duplicated, active, unexplained or incorrectly certified.")
        removed.add(identity)
    return removed


def validate_feature_baseline(inventory: dict, baseline: dict) -> None:
    """Freeze the declared feature set; implementation work may only append new identities."""
    previous, current = baseline.get("features", []), inventory.get("features", [])
    if (baseline.get("schemaVersion") != 1 or inventory.get("schemaVersion") != 1
            or not previous or not current or baseline.get("baselineRevision") != inventory.get("baselineRevision")):
        raise RuntimeError("Feature review requires its complete frozen identity baseline.")
    old_ids = [row.get("featureId") for row in previous]
    ids = [row.get("featureId") for row in current]
    scoped_removals(inventory, baseline, "removedFeatures", ids)
    if (any(not isinstance(identity, str) or not identity.strip() for identity in ids + old_ids)
            or len(set(ids)) != len(ids) or len(set(old_ids)) != len(old_ids) or ids[:len(old_ids)] != old_ids):
        raise RuntimeError("Feature baseline rows were omitted, duplicated, reordered or assigned different identities.")
    for old, row in zip(previous, current):
        definition = row.get("historicalDefinition", row)
        if baseline.get("historicalDefinitionRevision") and "historicalDefinition" not in row:
            raise RuntimeError("A retained feature needs its explicit frozen historical definition: " + old["featureId"])
        if any(definition.get(key) != old.get(key) for key in ("owner", "basis", "origin")):
            raise RuntimeError("A frozen feature identity changed its owner or original definition: " + old["featureId"])


def read_report(archive_path: Path) -> dict:
    if archive_path.stat().st_size > 64 * 1024 ** 2:
        raise RuntimeError("The feature evidence archive exceeds its bounded input size.")
    with zipfile.ZipFile(archive_path) as archive:
        matches = [entry for entry in archive.infolist() if entry.filename == "report.json"]
        if len(matches) != 1 or matches[0].file_size > 16 * 1024 ** 2:
            raise RuntimeError("Feature evidence requires one bounded exact report.json; no archive extraction is performed.")
        with archive.open(matches[0]) as stream:
            return json.loads(stream.read(16 * 1024 ** 2 + 1))


def validate_readiness(inventory: dict, implementation: dict, root: Path, required_hosts: set[str]) -> list[dict]:
    """Review declarations before a commit; no receipt or certification is fabricated here."""
    if implementation.get("implementationReady") is not True or implementation.get("releaseReady") is not False:
        raise RuntimeError("Source declarations require implementationReady=true and releaseReady=false; certification is derived only from current receipts.")
    features = inventory.get("features", [])
    ids = [feature.get("featureId") for feature in features]
    if not ids or any(not isinstance(item, str) or not item.strip() for item in ids) or len(set(ids)) != len(ids):
        raise RuntimeError("The release feature inventory is empty or has duplicate/invalid identities.")
    for feature in features:
        identity = feature["featureId"]
        if feature.get("status") != "implementationReady":
            raise RuntimeError("A feature lacks its explicit implementationReady source review: " + identity)
        rationale = feature.get("acceptanceRationale")
        if not isinstance(rationale, str) or not rationale.strip() or len(rationale) > 4096:
            raise RuntimeError("A feature lacks a reviewed explanation of its exact executable assertions: " + identity)
        paths = feature.get("implementation", [])
        if not paths or any(not isinstance(path, str) or Path(path).is_absolute()
                            or not (root / path).resolve().is_relative_to(root.resolve()) or not (root / path).is_file() for path in paths):
            raise RuntimeError("A feature lacks its complete existing neutral implementation paths: " + identity)
        hosts = feature.get("requiredHosts", [])
        if (not hosts or len(set(hosts)) != len(hosts) or not set(hosts).issubset(required_hosts)
                or set(hosts) != required_hosts and not feature.get("scopeJustification", "").strip()):
            raise RuntimeError("A feature needs reviewed required hosts and an explicit reason for any finite host scope: " + identity)
        mappings = feature.get("releaseEvidence", [])
        if not mappings or {mapping.get("host") for mapping in mappings} != set(hosts):
            raise RuntimeError("A feature lacks its explicit acceptance mappings for every required host: " + identity)
        if identity == FEATURE_ID and (set(hosts) != required_hosts
                or any(row.get("kind") != "global" or row.get("proofId") != PROOF_ID for row in mappings)):
            raise RuntimeError("Desktop/browser/NativeAOT validation requires its exact global execution proof on every launch host.")
        seen = set()
        for mapping in mappings:
            host, kind = mapping.get("host"), mapping.get("kind")
            if kind == "test":
                project, pattern = mapping.get("project", ""), mapping.get("match", "")
                if (not isinstance(project, str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.-]*", project)
                        or not isinstance(pattern, str) or len(pattern) > 1024
                        or not re.fullmatch(r"\^[A-Za-z_]\w*(?:\\\.[A-Za-z_]\w*)+\$", pattern)):
                    raise RuntimeError("A feature test mapping requires an exact project and fully qualified test method: " + identity)
                re.compile(pattern)
                cases = mapping.get("requiredCases")
                if (not isinstance(cases, list) or not cases or len(cases) > 10000
                        or any(not isinstance(case, str) or not case.strip() or len(case) > 8192 or "\0" in case for case in cases)
                        or len(set(cases)) != len(cases)):
                    raise RuntimeError("A test proof requires its reviewed exact unique literal case display names: " + identity)
                key = (host, kind, project, pattern)
            elif kind == "category":
                category = mapping.get("category")
                if not isinstance(category, str) or not category.strip() or len(category) > 256:
                    raise RuntimeError("A feature category mapping requires an exact structured category: " + identity)
                key = (host, kind, category)
            elif kind == "global":
                if identity != FEATURE_ID or mapping.get("proofId") != PROOF_ID:
                    raise RuntimeError("A global proof cannot replace unrelated feature assertions: " + identity)
                key = (host, kind, PROOF_ID)
            else:
                raise RuntimeError("An unknown feature proof kind cannot certify a release: " + identity)
            if key in seen:
                raise RuntimeError("A feature repeats an ambiguous acceptance mapping: " + identity)
            seen.add(key)
    return features


def validate_test_mapping(mapping: dict, report: dict, identity: str) -> dict:
    """Match every reviewed literal case against its unique actual executed test suite."""
    project, pattern = mapping.get("project", ""), mapping.get("match", "")
    if not project or not pattern or len(pattern) > 1024:
        raise RuntimeError("A feature test mapping requires an exact project and bounded method pattern: " + identity)
    expression = re.compile(pattern)
    suites = [suite for suite in report.get("executedTests", [])
              if Path(suite.get("trx", "").replace("\\", "/")).name == project + ".trx"]
    if len(suites) != 1:
        raise RuntimeError("A feature has no unique executed test project: " + identity + "/" + project)
    if not isinstance(suites[0].get("sha256"), str) or not re.fullmatch(r"[0-9a-f]{64}", suites[0]["sha256"]):
        raise RuntimeError("A feature test proof lacks the actual TRX content digest: " + identity)
    matched = [row for row in suites[0].get("results", []) if expression.search(row.get("name", ""))]
    if not matched or any(row.get("outcome") != "Passed" for row in matched):
        raise RuntimeError("A required feature test is missing, failed or not executed: " + identity)
    names = [row.get("displayName") for row in matched]
    required = mapping["requiredCases"]
    if (any(not isinstance(name, str) or not name for name in names)
            or len(set(names)) != len(names) or set(names) != set(required)):
        raise RuntimeError("The executed test cases differ from the reviewed exact display names or repeat a case: " + identity)
    return {"host": mapping["host"], "kind": "test", "project": project, "match": pattern,
            "executedPassed": len(matched), "requiredCases": required, "trxSha256": suites[0]["sha256"]}


def review_executed_cases(features: list[dict], report: dict) -> int:
    """Check this host's exact case declarations without claiming full release certification."""
    reviewed = 0
    for feature in features:
        for mapping in feature["releaseEvidence"]:
            if mapping["host"] == report["platform"] and mapping["kind"] == "test":
                validate_test_mapping(mapping, report, feature["featureId"])
                reviewed += 1
    if not reviewed:
        raise RuntimeError("The host has no reviewed exact executed-case mappings.")
    return reviewed


def validate(inventory: dict, implementation: dict, reports: list[dict], revision: str, content: str,
             root: Path, required_hosts: set[str], global_proofs: dict | None = None) -> dict:
    features = validate_readiness(inventory, implementation, root, required_hosts)
    indexed = {}
    for report in reports:
        source = report.get("source", {})
        host = report.get("platform")
        if (host not in required_hosts or host in indexed or report.get("schemaVersion") != 3
                or report.get("status") != "passed" or report.get("scope") not in ("one-host-maintenance-candidate", "generator-platform-smoke")
                or report.get("usesPrebuiltOutputs") is not False or source.get("revision") != revision
                or source.get("workingTreeDirty") is not False or source.get("checkedOutSourceSha256") != content):
            raise RuntimeError("Feature evidence did not come from a fresh clean build of this exact release source/host.")
        if report.get("scope") == "generator-platform-smoke":
            from importlib.util import module_from_spec, spec_from_file_location
            spec = spec_from_file_location("generator_smoke_contract", ROOT / "scripts/run-generator-smoke.py")
            smoke = module_from_spec(spec); spec.loader.exec_module(smoke)
            rows = [row for suite in report.get("executedTests", []) for row in suite.get("results", [])]
            if host == "windows-x64" or report.get("fullFunctionalBaseline") is not False:
                raise RuntimeError("A platform smoke cannot replace the complete functional baseline or omit its real consumer cases.")
            smoke.verify_cases({"results": rows}, host)
        indexed[host] = report
    if indexed.keys() != required_hosts:
        raise RuntimeError("The release lacks its complete declared desktop feature evidence hosts.")
    verified = []
    for feature in features:
        identity = feature["featureId"]
        mappings = feature["releaseEvidence"]
        proofs = []
        seen = set()
        for mapping in mappings:
            host, kind = mapping.get("host"), mapping.get("kind")
            report = indexed[host]
            if kind == "test":
                proof = validate_test_mapping(mapping, report, identity)
                key = (host, kind, mapping["project"], mapping["match"])
            elif kind == "category":
                category = mapping.get("category", "")
                if category == "installed-host-products":
                    installed = (global_proofs or {}).get("installedProducts", {})
                    if (installed.get("sourceRevision") != revision or installed.get("checkedOutSourceSha256") != content
                            or not installed.get("artifacts") or not installed.get("productRunId")
                            or any(not re.fullmatch(r"[0-9a-f]{64}", item.get("verificationSha256", "")) for item in installed["artifacts"])):
                        raise RuntimeError("Installed-product assertions require their exact independently validated package archive: " + identity)
                    proof = {"host": host, "kind": kind, "category": category, "acceptedProducts": installed}
                else:
                    candidates = [row for row in report.get("categories", []) if row.get("name") == category]
                    if len(candidates) != 1 or candidates[0].get("status") != "passed":
                        raise RuntimeError("A required structured feature acceptance category did not pass: " + identity + "/" + category)
                    proof = {"host": host, "kind": kind, "category": category}
                key = (host, kind, category)
            elif kind == "global":
                verified_host = (global_proofs or {}).get(PROOF_ID, {}).get("hosts", {}).get(host, {})
                if (verified_host.get("status") != "verified" or verified_host.get("sourceRevision") != revision
                        or verified_host.get("checkedOutSourceSha256") != content):
                    raise RuntimeError("The required exact global execution proof is missing or stale: " + identity + "/" + host)
                proof = {"host": host, "kind": kind, "proofId": PROOF_ID, **verified_host}
                key = (host, kind, PROOF_ID)
            else:
                raise RuntimeError("An unknown feature proof kind cannot certify a release: " + identity)
            if key in seen:
                raise RuntimeError("A feature repeats an ambiguous acceptance mapping: " + identity)
            seen.add(key)
            proofs.append(proof)
        verified.append({"featureId": identity, "status": "verified", "sourceRevision": revision,
                         "checkedOutSourceSha256": content, "proofs": proofs})
    return {"schemaVersion": 1, "success": True, "implementationReady": True, "featureAcceptanceVerified": True,
            "releaseReady": False, "sourceRevision": revision, "checkedOutSourceSha256": content,
            "hosts": sorted(indexed), "features": verified}


def configuration_declarations(inventory: dict, baseline: dict) -> tuple[list[dict], dict]:
    """Require exact baseline identities and reviewed assertions, independently of source correspondence."""
    original, entries = baseline.get("entries", []), inventory.get("entries", [])
    if (baseline.get("schemaVersion") != 1 or inventory.get("schemaVersion") != 1
            or not original or not entries or baseline.get("baseline") != inventory.get("baseline")):
        raise RuntimeError("Configuration certification requires its complete frozen baseline and current inventory.")
    ids = [entry.get("configurationId") for entry in entries]
    expected_ids = [entry.get("configurationId") for entry in original]
    if any(not isinstance(value, str) or not re.fullmatch(r"CFG[0-9]{4,}", value) for value in expected_ids):
        raise RuntimeError("Configuration baseline has invalid stable identities.")
    removed = scoped_removals(inventory, baseline, "removedConfiguration", ids)
    ordered_ids = expected_ids + ["CFG" + format(index, "04d") for index in range(max(int(value[3:]) for value in expected_ids) + 1, max(int(value[3:]) for value in expected_ids) + 1 + len(ids) - len(expected_ids))] if removed else ["CFG" + format(index, "04d") for index in range(1, len(ids) + 1)]
    if (any(not isinstance(identity, str) or not re.fullmatch(r"CFG[0-9]{4,}", identity) for identity in ids)
            or len(set(ids)) != len(ids) or len(set(expected_ids)) != len(expected_ids)
            or ids[:len(expected_ids)] != expected_ids
            or ids != ordered_ids):
        raise RuntimeError("Configuration baseline rows were omitted, duplicated, reordered or assigned unstable identities.")
    by_id = {entry["configurationId"]: entry for entry in entries}
    for previous in original:
        current = by_id[previous["configurationId"]]
        if any(current.get(field) != previous.get(field) for field in ("source", "member", "type")):
            raise RuntimeError("A frozen configuration identity changed its original source/member/type: " + previous["configurationId"])
    projected = []
    for entry in entries:
        identity = entry["configurationId"]
        rationale = entry.get("acceptanceRationale")
        if not isinstance(rationale, str) or not rationale.strip() or len(rationale) > 4096:
            raise RuntimeError("A configuration row lacks a reviewed explanation of its exact executable assertions: " + identity)
        if not entry.get("releaseEvidence"):
            raise RuntimeError("A configuration row has no actual same-revision test proof: " + identity)
        for proof in entry["releaseEvidence"]:
            if (proof.get("kind") != "test" or not isinstance(proof.get("match"), str)
                    or not re.fullmatch(r"\^[A-Za-z_]\w*(?:\\\.[A-Za-z_]\w*)+\$", proof["match"])):
                raise RuntimeError("Configuration proofs must select exact fully qualified test methods, never a broad passing suite/category: " + identity)
        # Source correspondence is deliberately not consulted or promoted here.
        projected.append({key: entry[key] for key in ("status", "implementation", "requiredHosts", "releaseEvidence", "scopeJustification", "acceptanceRationale") if key in entry}
                         | {"featureId": identity})
    return projected, by_id


def validate_configurations(inventory: dict, baseline: dict, implementation: dict, reports: list[dict],
                            revision: str, content: str, root: Path, required_hosts: set[str]) -> list[dict]:
    projected, by_id = configuration_declarations(inventory, baseline)
    proven = validate({"features": projected}, implementation, reports, revision, content, root, required_hosts)["features"]
    for proof in proven:
        identity = proof.pop("featureId")
        proof["configurationId"] = identity
        proof["acceptanceRationale"] = by_id[identity]["acceptanceRationale"]
        proof.update({field: by_id[identity][field] for field in ("source", "member", "type")})
    return proven


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--archive", action="append", type=Path)
    parser.add_argument("--revision")
    parser.add_argument("--check-readiness", action="store_true", help="Review source declarations only; never certify a release.")
    parser.add_argument("--check-executed-cases", type=Path, help="Review this current host report's exact cases; never certify a release.")
    parser.add_argument("--workflow-evidence", type=Path, help="Authenticated workflow/run observations created by release preflight.")
    parser.add_argument("--product-archive", action="append", help="Exact required artifact name=downloaded ZIP path.")
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    gates = json.loads((ROOT / "eng/acceptance/required-release-gates.json").read_text(encoding="utf-8"))
    inventory = json.loads((ROOT / "eng/acceptance/feature-inventory.json").read_text(encoding="utf-8"))
    validate_feature_baseline(inventory,
        json.loads((ROOT / gates["featureBaseline"]).read_text(encoding="utf-8")))
    implementation = json.loads((ROOT / "eng/acceptance/implementation-status.json").read_text(encoding="utf-8"))
    hosts = {entry["host"] for entry in gates["requiredFeatureEvidence"]}
    configurations = json.loads((ROOT / inventory["configurationInventory"]).read_text(encoding="utf-8"))
    baseline = json.loads((ROOT / gates["configurationBaseline"]).read_text(encoding="utf-8"))
    if args.check_executed_cases:
        if args.check_readiness or args.archive or args.revision or args.output or args.workflow_evidence or args.product_archive:
            parser.error("Executed-case review accepts only its current host report, without release certification inputs.")
        if args.check_executed_cases.stat().st_size > 16 * 1024 ** 2:
            raise RuntimeError("The host report exceeds its bounded input size.")
        report = json.loads(args.check_executed_cases.read_text(encoding="utf-8"))
        source = source_identity(ROOT)
        if (report.get("source") != source or report.get("schemaVersion") != 3
                or report.get("status") != "passed" or type(report.get("usesPrebuiltOutputs")) is not bool
                or report.get("platform") not in hosts or report.get("scope") != "one-host-maintenance-candidate"):
            raise RuntimeError("Executed-case review requires this exact current-source host report.")
        features = validate_readiness(inventory, implementation, ROOT, hosts)
        projected, _ = configuration_declarations(configurations, baseline)
        validate_readiness({"features": projected}, implementation, ROOT, hosts)
        count = review_executed_cases([*features, *projected], report)
        print("Reviewed exact executed-case mappings: " + str(count) + "; no complete release certification was performed.")
        return
    if args.check_readiness:
        if args.archive or args.revision or args.output or args.workflow_evidence or args.product_archive:
            parser.error("--check-readiness cannot accept certification inputs or emit a release receipt.")
        features = validate_readiness(inventory, implementation, ROOT, hosts)
        projected, _ = configuration_declarations(configurations, baseline)
        validate_readiness({"features": projected}, implementation, ROOT, hosts)
        print("Reviewed implementation declarations only: " + str(len(features)) + " features and " + str(len(projected))
              + " configuration rows; no CI acceptance or release certification was performed.")
        return
    if not args.archive or not args.revision:
        parser.error("Certification requires --revision and the complete --archive set.")
    source = source_identity(ROOT)
    if source["revision"] != args.revision or source["workingTreeDirty"]:
        raise RuntimeError("Release feature verification requires the exact clean checkout.")
    reports = [read_report(path) for path in args.archive]
    global_proofs = None
    if args.workflow_evidence or args.product_archive:
        if not args.workflow_evidence or not args.product_archive or args.workflow_evidence.stat().st_size > 2 * 1024 ** 2:
            raise RuntimeError("Global feature certification requires its complete bounded workflow observations and installed archive set.")
        product_archives = {}
        for item in args.product_archive:
            name, separator, path = item.partition("=")
            if not separator or not name or not path or name in product_archives:
                raise RuntimeError("A global product archive declaration is invalid or duplicated.")
            product_archives[name] = Path(path)
        global_proofs = verify_global_features(gates, json.loads(args.workflow_evidence.read_text(encoding="utf-8")),
            product_archives, args.revision, source["checkedOutSourceSha256"])
    result = validate(inventory, implementation, reports, args.revision, source["checkedOutSourceSha256"], ROOT, hosts, global_proofs)
    if global_proofs is not None:
        result["globalExecutionEvidence"] = global_proofs
    result["configurationEntries"] = validate_configurations(
        configurations, baseline,
        implementation, reports, args.revision, source["checkedOutSourceSha256"], ROOT, hosts)
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
    print("Verified same-revision implementation and actual acceptance mappings for " + str(len(result["features"]))
          + " features and " + str(len(result["configurationEntries"])) + " configuration rows.")


if __name__ == "__main__":
    main()
